<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; require_admin();
$admin_title='News'; $admin_heading='News Management'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf($_POST['csrf']??null)){http_response_code(419);exit('Invalid CSRF token.');}
 $action=$_POST['action']??'';$id=(int)($_POST['id']??0);$title=trim($_POST['title']??'');$title_kh=trim($_POST['title_kh']??'');$content=trim($_POST['content']??'');$content_kh=trim($_POST['content_kh']??'');$author=trim($_POST['author']??'');$status=in_array($_POST['status']??'published',['draft','published','inactive'],true)?$_POST['status']:'published';
 if($action!=='delete' && ($title===''||$content===''))$error='Title and content are required.';
 elseif($action==='add'){$s=$pdo->prepare('INSERT INTO news(title,title_kh,content,content_kh,author,status,published_at) VALUES(?,?,?,?,?,?,CASE WHEN ?="published" THEN NOW() ELSE NULL END)');$s->execute([$title,$title_kh,$content,$content_kh,$author,$status,$status]);header('Location: news.php');exit;}
 elseif($action==='edit'){$s=$pdo->prepare('UPDATE news SET title=?,title_kh=?,content=?,content_kh=?,author=?,status=?,published_at=CASE WHEN ?="published" AND published_at IS NULL THEN NOW() ELSE published_at END WHERE id=?');$s->execute([$title,$title_kh,$content,$content_kh,$author,$status,$status,$id]);header('Location: news.php');exit;}
 elseif($action==='delete'){$pdo->prepare('DELETE FROM news WHERE id=?')->execute([$id]);header('Location: news.php');exit;}
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM news WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT * FROM news ORDER BY created_at DESC')->fetchAll();
require __DIR__.'/layout.php';
?><div class="admincard form"><div class="head"><div><span class="eyebrow"><?= $edit?'EDIT NEWS':'NEW NEWS' ?></span><h2><?= $edit?'Edit News':'Add News' ?></h2></div></div><?php if($error):?><div class="alert err"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'edit':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="two"><label>Title<input name="title" value="<?=htmlspecialchars($edit['title']??'')?>" required></label><label>Title (Khmer)<input name="title_kh" value="<?=htmlspecialchars($edit['title_kh']??'')?>"></label></div><label>Content<textarea name="content" rows="5" required><?=htmlspecialchars($edit['content']??'')?></textarea></label><label>Content (Khmer)<textarea name="content_kh" rows="5"><?=htmlspecialchars($edit['content_kh']??'')?></textarea></label><div class="two"><label>Author<input name="author" value="<?=htmlspecialchars($edit['author']??$_SESSION['user_name']??'Admin')?>"></label><label>Status<select name="status"><?php foreach(['draft','published','inactive'] as $st):?><option value="<?=$st?>" <?=($edit['status']??'published')===$st?'selected':''?>><?=ucfirst($st)?></option><?php endforeach;?></select></label></div><button class="btn"><?=$edit?'Save Changes':'Publish News'?></button><?php if($edit):?><a class="btn outline" href="news.php">Cancel</a><?php endif;?></form></div>
<div class="admincard"><div class="head"><h2>News</h2></div><div class="tablewrap"><table><thead><tr><th>Title</th><th>Author</th><th>Status</th><th>Published</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=htmlspecialchars($r['title'])?></b><small><?=htmlspecialchars($r['title_kh']??'')?></small></td><td><?=htmlspecialchars($r['author']??'')?></td><td><?=htmlspecialchars(ucfirst($r['status']))?></td><td><?=htmlspecialchars($r['published_at']??'—')?></td><td><a class="action-link" href="news.php?edit=<?=$r['id']?>">Edit</a> <form style="display:inline" method="post" onsubmit="return confirm('Delete this news item?')"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="action-link danger" type="submit">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/end.php';?>